function clone(value){return JSON.parse(JSON.stringify(value));}
function loadData(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(saved && saved.settings && Array.isArray(saved.scenarios))return saved;}catch{}return clone(DEFAULTS);}
let data=loadData();
let server={available:false,configured:false};
let view={type:'home',scenarioId:null,step:0,filter:'All',query:''};
let editor={unlocked:false,tab:'guides',selectedId:null,draft:null};
let timer={mode:null,startedAt:0,elapsed:0,running:false,interval:null,bpm:110,lastBeat:-1,audio:null,alerted:false};
const root=$('#app');

async function saveData(){try{if(server.available){const response=await fetch('/api/content',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),credentials:'same-origin'});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save content.');}else localStorage.setItem(STORAGE_KEY,JSON.stringify(data));return true;}catch(error){toast(error.message||'Could not save content.');return false;}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.classList.remove('show'),3500);}
function phoneHref(){const cleaned=String(data.settings.emergencyNumber||'').replace(/[^0-9+]/g,'');return cleaned?`tel:${cleaned}`:'#';}
function updateShell(){document.title=`${data.settings.brand||'steady'} — First aid, one step at a time`;$('#brand-name').innerHTML=`${esc(data.settings.brand||'steady')}<span class="brand-dot">.</span>`;$('#footer-note').textContent=data.settings.footerNote||'';document.querySelectorAll('.emergency-number').forEach(el=>el.textContent=data.settings.emergencyNumber||'Local number');document.querySelectorAll('.emergency-link').forEach(el=>el.href=phoneHref());}
function theme(color){return ({coral:{tint:'#fff0eb',tone:'#e36f57'},orange:{tint:'#fff2e5',tone:'#d98a44'},purple:{tint:'#f1effa',tone:'#8069bd'},green:{tint:'#e8f3ed',tone:'#368b68'}}[color]||{tint:'#e8f3ed',tone:'#368b68'});}
function render(){updateShell();if(view.type==='guide')renderGuide();else renderHome();}
function goHome(scrollToGuides=false){stopTimer(true);view.type='home';view.scenarioId=null;view.step=0;render();history.replaceState(null,'','#home');requestAnimationFrame(()=>{if(scrollToGuides)$('#guides')?.scrollIntoView({behavior:'smooth'});else scrollTo({top:0,behavior:'smooth'});});}
function openGuide(id){const scenario=data.scenarios.find(item=>item.id===id);if(!scenario){toast('Guide not found.');return;}stopTimer(true);view.type='guide';view.scenarioId=id;view.step=0;render();history.replaceState(null,'',`#guide/${encodeURIComponent(id)}`);scrollTo({top:0,behavior:'smooth'});}
function activeScenario(){return data.scenarios.find(item=>item.id===view.scenarioId);}
function renderHome(){const s=data.settings;root.innerHTML=`<div class="page-wrap"><section class="home-hero" id="home"><div><span class="eyebrow">${esc(s.heroEyebrow)}</span><h1>${heroTitle(s.heroTitle)}</h1><p class="hero-lead">${esc(s.heroDescription)}</p><div class="hero-actions"><button class="primary-button" type="button" data-scroll="guides">Find a guide ${icon('arrow')}</button><a class="secondary-button emergency-link" href="${esc(phoneHref())}">${icon('phone')} Call emergency services</a></div><div class="hero-note">${icon('shield')} Emergency number for ${esc(s.locationLabel)}: ${esc(s.emergencyNumber)}. ${esc(s.emergencyNote)}</div></div><div class="hero-art" aria-hidden="true"><span class="float-cross a">+</span><span class="float-cross b">+</span><div class="art-chip one">${icon('check')} Stay calm</div><div class="art-chip two">${icon('phone')} Call for help</div><div class="art-chip three">${icon('clock')} One step at a time</div><div class="art-card"><div class="art-kicker">FIRST AID GUIDE</div><div class="art-line"></div><div class="art-line short"></div><div class="art-heart">${icon('heart')}</div><div class="art-bottom"><span></span><span></span><span></span></div></div></div></section><section class="guides-section" id="guides"><div class="section-top"><div><span class="eyebrow">QUICK START</span><h2>${esc(s.sectionTitle)}</h2><p>${esc(s.sectionDescription)}</p></div><label class="search-box">${icon('search')}<input id="guide-search" type="search" placeholder="Search a symptom or situation..." value="${esc(view.query)}" aria-label="Search guides"></label></div><div class="filter-row" id="filter-row"></div><div class="guide-grid" id="guide-grid"></div></section><section class="about-band" id="about"><div><span class="eyebrow">ABOUT STEADY</span><h2>${esc(s.aboutTitle)}</h2></div><div><p>${esc(s.aboutDescription)}</p><div class="about-features"><span>Clear steps</span><span>Built-in timers</span><span>Editable guides</span></div></div></section></div>`;renderFilters();renderCards();}
function heroTitle(value){const words=String(value||'').split(' ');const last=words.pop()||'';return `${esc(words.join(' '))} <em>${esc(last)}</em>`;}
function renderFilters(){const categories=['All',...new Set(data.scenarios.filter(item=>item.featured!==false).map(item=>item.category||'Other'))];$('#filter-row').innerHTML=categories.map(cat=>`<button type="button" class="filter-chip ${view.filter===cat?'active':''}" data-filter="${esc(cat)}">${esc(cat)}</button>`).join('');}
function renderCards(){const q=view.query.trim().toLowerCase();const filtered=data.scenarios.filter(item=>item.featured!==false && (view.filter==='All'||item.category===view.filter) && (!q||`${item.title} ${item.subtitle} ${item.intro}`.toLowerCase().includes(q)));$('#guide-grid').innerHTML=filtered.length?filtered.map(item=>{const t=theme(item.color);return `<button type="button" class="guide-card" data-guide="${esc(item.id)}" style="--tint:${t.tint};--tone:${t.tone}"><span class="card-icon">${icon(item.icon||'shield')}</span><h3>${esc(item.title)}</h3><p>${esc(item.subtitle)}</p><span class="card-arrow">${icon('arrow')}</span></button>`;}).join(''):'<div class="empty-state">No guides found. Try another word or category.</div>';}
function illustrationMarkup(name){const diagrams={compressions:['hand','heart','PUSH DOWN'], 'side-position':['person','lungs','ON THEIR SIDE'], 'back-blows':['hand','person','BETWEEN SHOULDERS'],thrusts:['hand','person','IN & UP'], 'direct-pressure':['hand','drop','HOLD PRESSURE'], 'cool-burn':['drop','flame','COOL WATER']};const parts=diagrams[name];return parts?`<div class="visual-diagram"><span class="diagram-badge">${icon(parts[0])}</span><span class="diagram-arrow">${icon('arrow')}</span><span class="diagram-badge">${icon(parts[1])}</span><span class="diagram-caption">${parts[2]}</span></div>`:`<div class="visual-icon">${icon(name||'shield')}</div>`;}
function renderGuide(){const item=activeScenario();if(!item){goHome();return;}const step=item.steps[view.step];if(!step){view.step=0;return renderGuide();}const t=theme(item.color);const pct=(view.step+1)/item.steps.length*100;const branch=item.branch&&view.step===item.steps.length-1?`<div class="branch-box"><h3>${esc(item.branch.prompt||'Choose what you see')}</h3><div class="branch-options">${(item.branch.options||[]).map(option=>`<button class="branch-button" type="button" data-guide="${esc(option.target)}">${esc(option.label)} ${icon('arrow')}</button>`).join('')}</div></div>`:'';const image=safeImage(step.image);root.innerHTML=`<div class="page-wrap guide-page"><button class="back-link" type="button" data-home="true">${icon('arrow-left')} All guides</button><div class="guide-head"><div><span class="eyebrow">STEP-BY-STEP GUIDE</span><h1>${esc(item.title)}</h1><p>${esc(item.intro)}</p></div><a class="emergency-button emergency-link" href="${esc(phoneHref())}">${icon('phone')} Call <b class="emergency-number">${esc(data.settings.emergencyNumber)}</b></a></div><div class="guide-layout"><aside class="steps-rail" aria-label="Steps"><div class="rail-label">YOUR STEPS</div>${item.steps.map((part,index)=>`<button class="rail-item ${index===view.step?'active':index<view.step?'done':''}" type="button" data-step="${index}"><span class="rail-num">${index<view.step?icon('check'):index+1}</span><span>${esc(part.title)}</span></button>`).join('')}<div class="rail-divider"></div><p class="rail-help">Move at your own pace. Follow your emergency dispatcher first.</p></aside><article class="action-card"><div class="progress-track"><span style="width:${pct}%"></span></div><div class="action-inner"><div class="action-kicker">STEP ${view.step+1} OF ${item.steps.length}</div><h2>${esc(step.title)}</h2><p class="action-body">${esc(step.body)}</p><div class="step-visual" style="--visual:${t.tint};--visual-tone:${t.tone}">${image?`<img src="${esc(image)}" alt="${esc(step.imageAlt||step.title)}">`:`${illustrationMarkup(step.illustration||item.icon||'shield')}<span class="visual-label">${esc(step.title)}</span>`}</div>${step.tip?`<div class="tip-box"><strong>REMEMBER</strong> ${esc(step.tip)}</div>`:''}</div>${branch}<div class="action-footer"><button class="secondary-button" type="button" data-prev="true" ${view.step===0?'disabled':''}>${icon('arrow-left')} Previous</button>${view.step<item.steps.length-1?`<button class="primary-button" type="button" data-next="true">Next step ${icon('arrow')}</button>`:`<button class="primary-button" type="button" data-home="true">All guides ${icon('arrow')}</button>`}</div></article><aside class="guide-aside"><div class="guide-aside-card"><div class="aside-icon">${icon('phone')}</div><h3>Need urgent help?</h3><p>${esc(data.settings.callScript)}</p><a class="emergency-button emergency-link" href="${esc(phoneHref())}">${icon('phone')} Call ${esc(data.settings.emergencyNumber||'now')}</a></div><div id="timer-slot"></div><div class="guide-aside-card source-card"><div class="small-label">GUIDANCE SOURCE</div><h3>Reviewed guidance</h3><p>Use this guide alongside emergency dispatch instructions.</p>${safeUrl(item.sourceUrl)?`<a href="${esc(safeUrl(item.sourceUrl))}" target="_blank" rel="noopener noreferrer">${esc(item.sourceLabel||'Read source')} ↗</a>`:''}</div></aside></div><div class="guide-cue">${icon('shield')}<span>${esc(item.cue||'Stay with the person and follow the emergency dispatcher.')}</span></div></div>`;if(step.timer&&!timer.mode)initTimer(step.timer);renderTimer();updateShell();}

function initTimer(config){timer.mode=config.type;timer.seconds=Number(config.seconds)||0;timer.bpm=Number(config.bpm)||110;timer.label=config.label||'Timer';timer.alert=config.alert||'Time threshold reached.';timer.elapsed=0;timer.startedAt=0;timer.running=false;timer.lastBeat=-1;timer.alerted=false;}
function stopTimer(clear=false){if(timer.interval){clearInterval(timer.interval);timer.interval=null;}timer.running=false;if(clear){timer.mode=null;timer.elapsed=0;timer.lastBeat=-1;}}
function timerElapsed(){return timer.elapsed+(timer.running?Date.now()-timer.startedAt:0);}
function formatTime(ms){const total=Math.max(0,Math.floor(ms/1000));return `${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function renderTimer(){const slot=$('#timer-slot');if(!slot)return;if(!timer.mode){slot.innerHTML='';return;}const elapsed=timerElapsed();const remaining=Math.max(0,timer.seconds*1000-elapsed);const display=timer.mode==='countdown'?formatTime(remaining):formatTime(elapsed);const count=timer.mode==='metronome'?`<p id="beat-count">Beat ${Math.floor(elapsed/(60000/timer.bpm))} · ${timer.bpm} per minute</p>`:`<p>${esc(timer.label)}</p>`;const warning=timer.mode==='stopwatch'&&timer.seconds&&elapsed>=timer.seconds*1000?timer.alert:timer.mode==='countdown'&&remaining===0?'Cooling time complete.':'';slot.innerHTML=`<div class="timer-card"><div class="small-label">${timer.mode==='metronome'?'RHYTHM GUIDE':timer.mode==='stopwatch'?'STOPWATCH':'COUNTDOWN'}</div><div class="timer-display" id="timer-display">${display}</div>${count}<div class="timer-controls"><button type="button" data-timer-toggle="true">${timer.running?'Pause':elapsed?'Resume':'Start'}</button><button type="button" class="secondary" data-timer-reset="true">Reset</button></div><p class="timer-warning" id="timer-warning">${warning}</p></div>`;}
function tickTimer(){if(!timer.running)return;const elapsed=timerElapsed();if(timer.mode==='countdown'&&elapsed>=timer.seconds*1000){timer.elapsed=timer.seconds*1000;stopTimer();toast('Cooling timer complete.');}if(timer.mode==='stopwatch'&&timer.seconds&&elapsed>=timer.seconds*1000&&!timer.alerted){timer.alerted=true;toast(timer.alert);}if(timer.mode==='metronome'){const beat=Math.floor(elapsed/(60000/timer.bpm));if(beat!==timer.lastBeat){timer.lastBeat=beat;beep();}}const display=$('#timer-display');if(display)display.textContent=timer.mode==='countdown'?formatTime(timer.seconds*1000-timerElapsed()):formatTime(timerElapsed());const beatLabel=$('#beat-count');if(beatLabel)beatLabel.textContent=`Beat ${Math.floor(timerElapsed()/(60000/timer.bpm))} · ${timer.bpm} per minute`;const warning=$('#timer-warning');if(warning)warning.textContent=timer.mode==='stopwatch'&&timer.seconds&&timerElapsed()>=timer.seconds*1000?timer.alert:timer.mode==='countdown'&&timerElapsed()>=timer.seconds*1000?'Cooling time complete.':'';if(!timer.running)renderTimer();}
function beep(){try{timer.audio ||= new (window.AudioContext||window.webkitAudioContext)();const oscillator=timer.audio.createOscillator();const gain=timer.audio.createGain();oscillator.type='sine';oscillator.frequency.value=650;gain.gain.setValueAtTime(.0001,timer.audio.currentTime);gain.gain.exponentialRampToValueAtTime(.12,timer.audio.currentTime+.01);gain.gain.exponentialRampToValueAtTime(.0001,timer.audio.currentTime+.08);oscillator.connect(gain).connect(timer.audio.destination);oscillator.start();oscillator.stop(timer.audio.currentTime+.09);}catch{}}
function toggleTimer(){if(timer.running){timer.elapsed=timerElapsed();stopTimer();}else{if(timer.mode==='countdown'&&timer.elapsed>=timer.seconds*1000)timer.elapsed=0;if(timer.mode==='metronome'){try{timer.audio ||= new (window.AudioContext||window.webkitAudioContext)();timer.audio.resume();}catch{}}timer.startedAt=Date.now();timer.running=true;timer.interval=setInterval(tickTimer,100);}renderTimer();}

root.addEventListener('click',event=>{const target=event.target.closest('button,a');if(!target)return;if(target.dataset.guide){openGuide(target.dataset.guide);return;}if(target.dataset.home){goHome();return;}if(target.dataset.scroll){document.getElementById(target.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}if(target.dataset.filter){view.filter=target.dataset.filter;renderFilters();renderCards();return;}if(target.dataset.step!==undefined){view.step=Number(target.dataset.step);renderGuide();return;}if(target.dataset.next){view.step++;renderGuide();return;}if(target.dataset.prev){view.step--;renderGuide();return;}if(target.dataset.timerToggle){toggleTimer();return;}if(target.dataset.timerReset){stopTimer(true);const current=activeScenario()?.steps.find(step=>step.timer);if(current?.timer)initTimer(current.timer);renderTimer();return;}});
root.addEventListener('input',event=>{if(event.target.id==='guide-search'){view.query=event.target.value;renderCards();}});
$('#brand-link').addEventListener('click',event=>{event.preventDefault();goHome();});
$('#nav-guides').addEventListener('click',event=>{event.preventDefault();goHome(true);});
$('#nav-about').addEventListener('click',event=>{event.preventDefault();goHome();setTimeout(()=>$('#about')?.scrollIntoView({behavior:'smooth'}),30);});

function showModal(){const modal=$('#editor-modal');modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';renderEditor();}
function closeModal(){const modal=$('#editor-modal');modal.classList.add('hidden');modal.setAttribute('aria-hidden','true');document.body.style.overflow='';}
document.querySelectorAll('.edit-trigger').forEach(button=>button.addEventListener('click',showModal));
$('#close-modal').addEventListener('click',closeModal);
$('#editor-modal').addEventListener('click',event=>{if(event.target.id==='editor-modal')closeModal();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#editor-modal').classList.contains('hidden'))closeModal();});

async function hashPassword(password,salt){if(!window.crypto?.subtle)throw new Error('Secure browser context required. Open this site on localhost or HTTPS.');const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:150000,hash:'SHA-256'},material,256);return [...new Uint8Array(bits)].map(byte=>byte.toString(16).padStart(2,'0')).join('');}
function authRecord(){if(server.available)return server.configured?{server:true}:null;try{return JSON.parse(localStorage.getItem(AUTH_KEY));}catch{return null;}}
function renderEditor(){const container=$('#editor-root');if(!editor.unlocked){const setup=!authRecord();container.innerHTML=`<div class="auth-panel"><span class="brand-mark">${icon('plus')}</span><h2 id="modal-title">${setup?'Create an editor password':'Unlock content editor'}</h2><p>${setup?'Set a password to protect editing. Guides remain available to everyone.':'Enter your password to add or change guides.'}</p><form id="auth-form"><div class="form-field"><label for="editor-password">Password</label><input id="editor-password" type="password" autocomplete="${setup?'new-password':'current-password'}" minlength="8" required placeholder="At least 8 characters"></div>${setup?`<div class="form-field"><label for="editor-confirm">Confirm password</label><input id="editor-confirm" type="password" autocomplete="new-password" minlength="8" required placeholder="Repeat your password"></div>`:''}<div class="auth-error" id="auth-error"></div><button type="submit" class="primary-button">${setup?'Create password':'Unlock editor'} ${icon('arrow')}</button></form><p class="field-hint" style="margin-top:17px">${server.available?'Your password is checked by this site’s server.':'This password protects this browser’s local editor. For shared publishing, use python server.py.'}</p></div>`;$('#editor-password',container).focus();return;}
  container.innerHTML=`<div class="editor-shell"><div class="editor-title"><span class="eyebrow">CONTENT MANAGEMENT</span><h2 id="modal-title">Edit your first aid site</h2><p>Changes save on this browser. Export a backup if you want to move them to another device.</p></div><div class="editor-tabs"><button class="editor-tab ${editor.tab==='guides'?'active':''}" data-tab="guides" type="button">Guides</button><button class="editor-tab ${editor.tab==='settings'?'active':''}" data-tab="settings" type="button">Site settings</button><button class="editor-tab ${editor.tab==='data'?'active':''}" data-tab="data" type="button">Backup & restore</button></div><div class="editor-content" id="editor-content"></div></div>`;renderEditorTab();}
function renderEditorTab(){const slot=$('#editor-content');if(!slot)return;if(editor.tab==='settings'){renderSettings(slot);return;}if(editor.tab==='data'){renderData(slot);return;}renderGuideEditor(slot);}
function inputField(label,key,value,options={}){const id=`field-${key}`;const hint=options.hint?`<small class="field-hint">${esc(options.hint)}</small>`:'';let input;if(options.type==='textarea')input=`<textarea id="${id}" data-setting="${esc(key)}" rows="${options.rows||3}">${esc(value)}</textarea>`;else input=`<input id="${id}" data-setting="${esc(key)}" type="${options.type||'text'}" value="${esc(value)}" ${options.required?'required':''}>`;return `<div class="form-field"><label for="${id}">${esc(label)}</label>${input}${hint}</div>`;}
function renderSettings(slot){const s=data.settings;slot.innerHTML=`<form id="settings-form" class="editor-form settings-form"><h3>Site copy and emergency contact</h3><div class="form-row">${inputField('Site name','brand',s.brand,{required:true})}${inputField('Emergency number','emergencyNumber',s.emergencyNumber,{required:true})}</div>${inputField('Location label','locationLabel',s.locationLabel)}${inputField('Hero eyebrow','heroEyebrow',s.heroEyebrow)}${inputField('Hero headline','heroTitle',s.heroTitle,{required:true})}${inputField('Hero description','heroDescription',s.heroDescription,{type:'textarea'})}<div class="form-row">${inputField('Guide section title','sectionTitle',s.sectionTitle)}${inputField('Guide section subtitle','sectionDescription',s.sectionDescription)}</div>${inputField('About title','aboutTitle',s.aboutTitle)}${inputField('About description','aboutDescription',s.aboutDescription,{type:'textarea'})}${inputField('Emergency note','emergencyNote',s.emergencyNote,{type:'textarea'})}${inputField('What to say when calling','callScript',s.callScript,{type:'textarea'})}${inputField('Footer note','footerNote',s.footerNote)}<div class="form-actions"><button class="primary-button" type="submit">Save site settings ${icon('check')}</button></div></form>`;}
function renderData(slot){slot.innerHTML=`<div class="editor-form data-panel"><h3>Back up your content</h3><p>Export your site settings and every guide as a JSON file. Import that file on another browser to restore your edits.</p><div class="data-buttons"><button type="button" class="secondary-button" data-export="true">${icon('download')} Export JSON</button><label class="secondary-button import-label">${icon('upload')} Import JSON<input type="file" id="import-file" accept="application/json,.json"></label></div><div class="note-box">${server.available?'Guides and uploaded pictures save on this site’s server. The password is stored as a salted verifier.':'Guides, uploaded pictures, and the password verifier are stored on this browser only.'} The exported file contains content but no password. Review imported medical instructions before publishing them.</div><div class="form-section-title">Start over</div><p>Restore the original example guides and settings. Export a backup first if you want to keep your edits.</p><button type="button" class="danger-button" data-restore="true">Restore sample content</button><button type="button" class="secondary-button" data-lock="true" style="margin-left:9px">Lock editor</button></div>`;}
function newScenario(){return {id:`guide-${Date.now()}`,title:'New guide',subtitle:'Describe the situation',category:'Other',icon:'shield',color:'green',featured:true,intro:'What this guide helps with.',cue:'Follow local emergency dispatcher instructions.',sourceLabel:'',sourceUrl:'',steps:[{title:'First step',body:'Write a clear action.',tip:'',illustration:'shield'}]};}
function ensureDraft(){if(!editor.draft){const item=data.scenarios.find(s=>s.id===editor.selectedId)||data.scenarios[0];editor.selectedId=item?.id||null;editor.draft=item?clone(item):newScenario();}}
function editorField(label,key,value,options={}){const id=`guide-${key}`;let control;if(options.type==='textarea')control=`<textarea id="${id}" data-guide-field="${esc(key)}" rows="${options.rows||3}">${esc(value)}</textarea>`;else if(options.type==='select')control=`<select id="${id}" data-guide-field="${esc(key)}">${options.values.map(option=>`<option value="${esc(option)}" ${String(value)===option?'selected':''}>${esc(option)}</option>`).join('')}</select>`;else control=`<input id="${id}" type="text" data-guide-field="${esc(key)}" value="${esc(value)}">`;return `<div class="form-field"><label for="${id}">${esc(label)}</label>${control}</div>`;}
function stepField(label,index,key,value,options={}){const id=`step-${index}-${key}`;const control=options.type==='textarea'?`<textarea id="${id}" data-step-index="${index}" data-step-field="${esc(key)}" rows="${options.rows||3}">${esc(value)}</textarea>`:options.type==='select'?`<select id="${id}" data-step-index="${index}" data-step-field="${esc(key)}">${options.values.map(option=>`<option value="${esc(option)}" ${String(value||'')===option?'selected':''}>${esc(option||'None')}</option>`).join('')}</select>`:`<input id="${id}" type="${options.type||'text'}" data-step-index="${index}" data-step-field="${esc(key)}" value="${esc(value)}">`;return `<div class="form-field"><label for="${id}">${esc(label)}</label>${control}</div>`;}
function renderGuideEditor(slot){ensureDraft();const d=editor.draft;const icons=['shield','person','lungs','hand','heart','drop','brain','bolt','flame','phone','clock'];const stepIcons=[...icons,'compressions','side-position','back-blows','thrusts','direct-pressure','cool-burn'];slot.innerHTML=`<div class="editor-grid"><div class="editor-list"><div class="editor-list-head">GUIDES <button type="button" data-new-guide="true" aria-label="Add guide">+</button></div>${data.scenarios.map(item=>`<button type="button" class="editor-list-item ${item.id===editor.selectedId?'active':''}" data-select-guide="${esc(item.id)}">${esc(item.title)}</button>`).join('')}</div><form class="editor-form" id="guide-form"><h3>${data.scenarios.some(item=>item.id===d.id)?'Edit guide':'New guide'}</h3><div class="form-row">${editorField('Guide title','title',d.title)}${editorField('Card subtitle','subtitle',d.subtitle)}</div><div class="form-row three">${editorField('Category','category',d.category)}${editorField('Icon','icon',d.icon,{type:'select',values:icons})}${editorField('Color','color',d.color,{type:'select',values:['green','coral','orange','purple']})}</div><label class="form-check"><input type="checkbox" data-guide-field="featured" ${d.featured!==false?'checked':''}> Show on home screen</label>${editorField('Guide introduction','intro',d.intro,{type:'textarea'})}${editorField('Important note','cue',d.cue,{type:'textarea'})}<div class="form-row">${editorField('Source title','sourceLabel',d.sourceLabel)}${editorField('Source URL','sourceUrl',d.sourceUrl)}</div><div class="form-section-title">Steps <button type="button" class="mini-button" data-add-step="true">+ Add step</button></div>${(d.steps||[]).map((step,index)=>`<div class="step-editor"><div class="step-editor-head"><span>STEP ${index+1}</span><div><button type="button" class="mini-button" data-move-step="${index}" data-direction="-1" aria-label="Move step up">↑</button> <button type="button" class="mini-button" data-move-step="${index}" data-direction="1" aria-label="Move step down">↓</button> <button type="button" class="icon-button" data-delete-step="${index}" aria-label="Delete step">${icon('close')}</button></div></div>${stepField('Step title',index,'title',step.title)}${stepField('What to do',index,'body',step.body,{type:'textarea',rows:4})}${stepField('Remember note',index,'tip',step.tip,{type:'textarea',rows:2})}<div class="form-row">${stepField('Illustration icon',index,'illustration',step.illustration,{type:'select',values:stepIcons})}${stepField('Image description',index,'imageAlt',step.imageAlt||'')}</div><div class="form-field"><label>Optional step image</label>${safeImage(step.image)?`<img class="step-image-preview" src="${esc(safeImage(step.image))}" alt="Current step image"><button type="button" class="mini-button" data-remove-image="${index}">Remove image</button>`:''}<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-image-step="${index}"><small class="field-hint">PNG, JPEG, WebP, or GIF, up to 1 MB. Stored in this browser.</small></div><div class="form-row three">${stepField('Timer type',index,'timerType',step.timer?.type||'',{type:'select',values:['','stopwatch','countdown','metronome']})}${stepField('Seconds / alert at',index,'timerSeconds',step.timer?.seconds||'',{type:'number'})}${stepField('Beats per minute',index,'timerBpm',step.timer?.bpm||'',{type:'number'})}</div>${stepField('Timer label',index,'timerLabel',step.timer?.label||'')}${stepField('Timer alert message',index,'timerAlert',step.timer?.alert||'')}</div>`).join('')}<div class="form-section-title">Decision after the final step <button type="button" class="mini-button" data-toggle-branch="true">${d.branch?'Remove decision':'+ Add decision'}</button></div>${d.branch?`<div class="step-editor">${editorField('Question','branchPrompt',d.branch.prompt)}${(d.branch.options||[]).map((option,index)=>`<div class="form-row">${stepField('Option '+(index+1)+' label',index,'branchLabel',option.label)}${stepField('Destination guide ID',index,'branchTarget',option.target)}</div><button type="button" class="mini-button" data-delete-option="${index}">Remove option</button>`).join('')}<button type="button" class="mini-button" data-add-option="true" style="margin-top:10px">+ Add option</button><p class="field-hint">Destination IDs: ${data.scenarios.map(item=>esc(item.id)).join(', ')}</p></div>`:''}<div class="form-actions"><button type="submit" class="primary-button">Save guide ${icon('check')}</button><button type="button" class="secondary-button" data-preview-guide="true">Preview</button><button type="button" class="danger-button" data-delete-guide="true">Delete guide</button></div></form></div>`;}

async function saveDraft(){const d=editor.draft;if(!d.title?.trim()||!d.intro?.trim()){toast('Add a guide title and introduction.');return false;}if(!Array.isArray(d.steps)||!d.steps.length||d.steps.some(step=>!step.title?.trim()||!step.body?.trim())){toast('Every guide needs at least one complete step.');return false;}if(d.branch&&(d.branch.options||[]).some(option=>!option.label?.trim()||!data.scenarios.some(item=>item.id===option.target)&&option.target!==d.id)){toast('Each decision needs a label and a valid destination guide ID.');return false;}const index=data.scenarios.findIndex(item=>item.id===d.id);const previous=index>=0?clone(data.scenarios[index]):null;if(index>=0)data.scenarios[index]=clone(d);else data.scenarios.push(clone(d));if(!await saveData()){if(index>=0)data.scenarios[index]=previous;else data.scenarios.pop();return false;}editor.selectedId=d.id;toast('Guide saved.');render();renderEditorTab();return true;}
function updateDraftField(target){const d=editor.draft;if(!d)return;const value=target.type==='checkbox'?target.checked:target.value;if(target.dataset.guideField){const key=target.dataset.guideField;if(key==='branchPrompt'){d.branch.prompt=value;}else d[key]=value;return;}if(target.dataset.stepField){const index=Number(target.dataset.stepIndex);const key=target.dataset.stepField;if(key==='branchLabel'||key==='branchTarget'){const option=d.branch?.options[index];if(option)option[key==='branchLabel'?'label':'target']=value;return;}const step=d.steps[index];if(!step)return;if(key==='timerType'){if(value)step.timer={type:value,seconds:Number(step.timer?.seconds)||0,bpm:Number(step.timer?.bpm)||110,label:step.timer?.label||'Timer',alert:step.timer?.alert||'Time threshold reached.'};else delete step.timer;return;}if(key==='timerSeconds'||key==='timerBpm'||key==='timerLabel'||key==='timerAlert'){if(!step.timer)step.timer={type:'stopwatch',seconds:0,bpm:110,label:'Timer',alert:'Time threshold reached.'};step.timer[key==='timerSeconds'?'seconds':key==='timerBpm'?'bpm':key==='timerAlert'?'alert':'label']=key==='timerLabel'||key==='timerAlert'?value:Number(value)||0;return;}step[key]=value;}}

const editorRoot=$('#editor-root');
editorRoot.addEventListener('submit',async event=>{
  event.preventDefault();
  if(event.target.id==='auth-form'){
    const password=$('#editor-password').value;
    const record=authRecord();
    const error=$('#auth-error');
    if(!record&&password!==$('#editor-confirm').value){error.textContent='Passwords do not match.';return;}
    try{
      if(server.available){
        const response=await fetch(record?'/api/login':'/api/setup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password}),credentials:'same-origin'});
        const result=await response.json();
        if(!response.ok)throw new Error(result.error||'Unable to unlock editor.');
        server.configured=true;
      }else if(!record){
        const bytes=crypto.getRandomValues(new Uint8Array(16));
        const salt=[...bytes].map(n=>n.toString(16).padStart(2,'0')).join('');
        const hash=await hashPassword(password,salt);
        localStorage.setItem(AUTH_KEY,JSON.stringify({salt,hash}));
      }else{
        const hash=await hashPassword(password,record.salt);
        if(hash!==record.hash){error.textContent='Incorrect password. Try again.';return;}
      }
      editor.unlocked=true;editor.tab='guides';renderEditor();toast('Editor unlocked.');
    }catch(err){error.textContent=err.message||'Unable to unlock editor.';}
    return;
  }
  if(event.target.id==='settings-form'){
    const previous=data.settings;
    const settings={...data.settings};
    event.target.querySelectorAll('[data-setting]').forEach(field=>settings[field.dataset.setting]=field.value);
    if(!settings.brand.trim()||!settings.emergencyNumber.trim()){toast('Site name and emergency number are required.');return;}
    data.settings=settings;
    if(await saveData()){render();toast('Site settings saved.');}else data.settings=previous;
    return;
  }
  if(event.target.id==='guide-form')await saveDraft();
});
editorRoot.addEventListener('input',event=>updateDraftField(event.target));
editorRoot.addEventListener('change',async event=>{const target=event.target;if(target.dataset.guideField||target.dataset.stepField)updateDraftField(target);if(target.dataset.imageStep!==undefined){const file=target.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)||file.size>1048576){toast('Choose a PNG, JPEG, WebP, or GIF under 1 MB.');target.value='';return;}const reader=new FileReader();reader.onload=()=>{editor.draft.steps[Number(target.dataset.imageStep)].image=reader.result;renderEditorTab();toast('Image added to draft. Save the guide to keep it.');};reader.readAsDataURL(file);}if(target.id==='import-file'){const file=target.files?.[0];if(!file)return;try{const imported=JSON.parse(await file.text());if(!imported||typeof imported.settings!=='object'||!Array.isArray(imported.scenarios)||!imported.scenarios.every(item=>item&&typeof item.id==='string'&&typeof item.title==='string'&&Array.isArray(item.steps)&&item.steps.length&&item.steps.every(step=>typeof step.title==='string'&&typeof step.body==='string'))){throw new Error('This is not a valid Steady backup.');}if(!confirm('Replace all current guides and site settings with this backup?'))return;const previous=data;data=imported;if(!await saveData()){data=previous;return;}editor.draft=null;editor.selectedId=null;render();renderEditor();toast('Backup imported.');}catch(err){toast(err.message||'Could not import that file.');}}});
editorRoot.addEventListener('click',async event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.tab){editor.tab=target.dataset.tab;renderEditor();return;}if(target.dataset.selectGuide){editor.selectedId=target.dataset.selectGuide;editor.draft=clone(data.scenarios.find(item=>item.id===editor.selectedId));renderEditorTab();return;}if(target.dataset.newGuide){editor.draft=newScenario();editor.selectedId=editor.draft.id;renderEditorTab();return;}if(target.dataset.addStep){editor.draft.steps.push({title:'New step',body:'Describe what to do.',tip:'',illustration:'shield'});renderEditorTab();return;}if(target.dataset.deleteStep!==undefined){if(editor.draft.steps.length===1){toast('A guide needs at least one step.');return;}editor.draft.steps.splice(Number(target.dataset.deleteStep),1);renderEditorTab();return;}if(target.dataset.moveStep!==undefined){const index=Number(target.dataset.moveStep),next=index+Number(target.dataset.direction);if(next>=0&&next<editor.draft.steps.length){[editor.draft.steps[index],editor.draft.steps[next]]=[editor.draft.steps[next],editor.draft.steps[index]];renderEditorTab();}return;}if(target.dataset.removeImage!==undefined){delete editor.draft.steps[Number(target.dataset.removeImage)].image;renderEditorTab();return;}if(target.dataset.toggleBranch){if(editor.draft.branch)delete editor.draft.branch;else editor.draft.branch={prompt:'What do you see?',options:[{label:'Option 1',target:data.scenarios[0]?.id||editor.draft.id},{label:'Option 2',target:data.scenarios[1]?.id||editor.draft.id}]};renderEditorTab();return;}if(target.dataset.addOption){editor.draft.branch.options.push({label:'New option',target:data.scenarios[0]?.id||editor.draft.id});renderEditorTab();return;}if(target.dataset.deleteOption!==undefined){editor.draft.branch.options.splice(Number(target.dataset.deleteOption),1);renderEditorTab();return;}if(target.dataset.previewGuide){if(await saveDraft()){closeModal();openGuide(editor.draft.id);}return;}if(target.dataset.deleteGuide){if(!data.scenarios.some(item=>item.id===editor.draft.id)){editor.draft=null;editor.selectedId=null;renderEditorTab();return;}if(!confirm(`Delete “${editor.draft.title}”?`))return;const id=editor.draft.id;const previous=clone(data.scenarios);data.scenarios=data.scenarios.filter(item=>item.id!==id);data.scenarios.forEach(item=>{if(item.branch){item.branch.options=item.branch.options.filter(option=>option.target!==id);if(!item.branch.options.length)delete item.branch;}});if(await saveData()){editor.draft=null;editor.selectedId=null;render();renderEditorTab();toast('Guide deleted.');}else data.scenarios=previous;return;}if(target.dataset.export){const payload=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(payload);const link=document.createElement('a');link.href=url;link.download=`steady-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}if(target.dataset.restore){if(!confirm('Restore the original sample content? Your current edits will be replaced.'))return;const previous=data;data=clone(DEFAULTS);if(await saveData()){editor.draft=null;editor.selectedId=null;render();renderEditor();toast('Sample content restored.');}else data=previous;return;}if(target.dataset.lock){if(server.available)await fetch('/api/logout',{method:'POST',credentials:'same-origin'});editor.unlocked=false;renderEditor();toast('Editor locked.');}});

window.addEventListener('hashchange',()=>{const match=location.hash.match(/^#guide\/(.+)$/);if(match){const id=decodeURIComponent(match[1]);if(view.scenarioId!==id)openGuide(id);}else if(view.type==='guide')goHome();});
async function bootstrap(){
  try{
    const statusResponse=await fetch('/api/status',{credentials:'same-origin'});
    if(statusResponse.ok){
      const status=await statusResponse.json();
      if(status.storage==='server'){
        server={available:true,configured:!!status.configured};
        editor.unlocked=!!status.authenticated;
        data=clone(DEFAULTS);
        const contentResponse=await fetch('/api/content',{credentials:'same-origin'});
        if(contentResponse.ok){
          const result=await contentResponse.json();
          data=result.content?.settings&&Array.isArray(result.content.scenarios)?result.content:clone(DEFAULTS);
        }
      }
    }
  }catch{}
  const initialMatch=location.hash.match(/^#guide\/(.+)$/);
  if(initialMatch&&data.scenarios.some(item=>item.id===decodeURIComponent(initialMatch[1])))openGuide(decodeURIComponent(initialMatch[1]));
  else render();
}
bootstrap();
